export type AppErrorCode =
  | 'AUTH_INVALID'
  | 'AUTH_PERMANENT'
  | 'TIMEOUT'
  | 'RATE_LIMIT'
  | 'PERMISSION'
  | 'CHANNEL_UNAVAILABLE'
  | 'CONVERSATION_STATE'
  | 'NETWORK'
  | 'CONFIG'
  | 'GATEWAY'
  | 'BILLING'
  | 'OVERLOADED'
  | 'MODEL_NOT_FOUND'
  | 'UNKNOWN';

/**
 * Every class the unified exit can render. Kept as a runtime list so copy,
 * retry and locale coverage can be audited exhaustively instead of by memory.
 */
export const APP_ERROR_CODES = [
  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** Recovery is either safe to perform again or requires an explicit user action. */
export type ErrorRecoveryScope = 'self-retry' | 'user-action-required';

/** Fixed, non-executable recovery verbs understood by the host and renderer. */
export type ErrorNextActionKind =
  | 'retry'
  | 'reauthenticate'
  | 'reconfigure'
  | 'open-settings'
  | 'contact-support';

/**
 * Bounded action parameters. A target identifies a settings/configuration area;
 * it is never a command, script, shell fragment, argv list or executable.
 */
export type ErrorNextActionTarget =
  | 'authentication'
  | 'channels'
  | 'conversation'
  | 'configuration'
  | 'billing'
  | 'model'
  | 'permissions';

ex**
 * The only action shape crossing the error envelope boundary. The `target`
 * key is optional and constrained by `ErrorNextActionTarget` at compile time.
 */
export type ErrorNextAction = {
  kind: ErrorNextActionKind;
  target?: ErrorNextActionTarget;
};

export type AppErrorRecovery = {
  retryable: boolean;
  scope: ErrorRecoveryScope;
  action?: ErrorNextAction;
  /** Unknown failures must be shown to the user rather than presented as fixable. */
  exposeRawError?: boolean;
};

/**
 * Exhaustive recovery policy for every AppErrorCode. The `satisfies` check
 * makes adding an error class without a stable recovery entry a compile error.
 */
export const APP_ERROR_RECOVERY = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  TIMEOUT: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  PERMISSION: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'contact-support', target: 'permissions' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'open-settings', target: 'channels' },
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reconfigure', target: 'conversation' },
  },
  NETWORK: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  CONFIG: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reconfigure', target: 'configuration' },
  },
  GATEWAY: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  BILLING: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'open-settings', target: 'billing' },
  },
  OVERLOADED: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  MODEL_NOT_FOUND: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reconfigure', target: 'model' },
  },
  UNKNOWN: {
    retryable: false,
    scope: 'user-action-required',
    exposeRawError: true,
