  requestId?: string;

  constructor(
    code: AppErrorCode,
    message: string,
    cause?: unknown,
    details?: Record<string, unknown>,
    requestId?: string,
  ) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    const recovery = APP_ERROR_RECOVERY[code];
    this.retryable = recovery.retryable;
